head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/

scwin.vScrenID = "ULDFIS00400_08.xml";
scwin.vKisCd = ""; // 조회조건 기업코드
scwin.vAcntclsDt = ""; // 조회조건 결산일자 
scwin.vArray = "";

/**
 *  화면이 최초 로드될때 실행되는 초기화 이벤트
 *  (초기 데이터 조회나 컴포넌트 설정)
 */
scwin.onpageload = function() {
    scwin.fn_Init();
};

/**
 *  현재 로딩된 페이지가 초기화되거나 종료될때(다른 화면으로 이동하거나 페이지를 닫기전) 발생하는 이벤트
 *  (주로 SPA(Single Page Application) 환경에서 전역 자원을 해제하거나 메모리 누수 방지)
 */
scwin.onpageunload = function() {

};

/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    // 결산일자 조회
    $p.parent().frame_head.getWindow().scwin.fn_SrchAcntclsDt();
    scwin.fn_Search();
};

/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {

    dlt_consNotesContLiabListRes.setData([]);

};

/**
 *  조회조건 유효성 체크
 */
scwin.fn_ChkValid = function() {

    //필수항목 체크
    vKisCd = $p.parent().frame_head.getWindow().scwin.fn_GetKisCd();
    vAcntclsDt = $p.parent().frame_head.getWindow().scwin.fn_GetAcntclsDt();

    if (vKisCd == "" || vAcntclsDt == "") {
        return false;
    }

    return true;

};

/**
 * 우발채무 조회
 */
scwin.fn_Search = async function() {

    //데이터셋 초기화
    scwin.fn_InitDs();

    // 조회조건 체크
    if (!scwin.fn_ChkValid()) {
        return;
    }

    dma_consNotesContLiabInfoReq.set("kisCd", vKisCd); // 기업코드
    dma_consNotesContLiabInfoReq.set("acntclsDt", vAcntclsDt); // 결산일자

    const res = await $c.sbm.execute(sbm_consNotesContLiab);
    dlt_consNotesContLiabListRes.setJSON(res.responseJSON.body);

    scwin.fn_AppendContents();

};

/**
 * 우발채무 정보 생성
 */
scwin.fn_AppendContents = function() {

    var strContent = "<div style='overflow-x:hidden;overflow-y:scroll;width:100%;height:575px;font-family:돋움체;'>";

    for (var nRow = 0; nRow < dlt_consNotesContLiabListRes.getTotalRow(); nRow++) {
        strContent = strContent + dlt_consNotesContLiabListRes.getCellData(nRow, "ctnt");
    }

    strContent = strContent + "</div>";
    var tbxContLiabObj = $p.getComponentById("tbx_contLiab").render;
    tbxContLiabObj.innerHTML = strContent;
    tbx_contLiab.setStyle("border", "1px solid blue");

};
